def transform(grid):
    # Reflect the input rotated 180 degrees across both axes, creating a
    # 3x3 reflected tiling. The central tile is the rotated input.
    base = [row[::-1] for row in grid[::-1]]
    h = len(base)
    row_order = list(range(h)) + list(range(h - 1, -1, -1)) + list(range(h))
    out = []
    for r in row_order:
        row = base[r] + base[r][::-1]
        out.append(row)
    return out
